import{_ as t,o,c as n,ag as i}from"./chunks/framework.B7PviQjB.js";const a="/docs/images/board/sections-selected.png",s="/docs/images/board/sections-list.png",u=JSON.parse('{"title":"Group ideas with sections","description":"Group sticky notes and other items on a board into titled sections that move together, and hide or lock a section.","frontmatter":{"title":"Group ideas with sections","description":"Group sticky notes and other items on a board into titled sections that move together, and hide or lock a section.","type":"how-to"},"headers":[],"relativePath":"board/sections.md","filePath":"board/sections.md"}'),r={name:"board/sections.md"};function c(l,e,d,h,p,m){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="group-ideas-with-sections" tabindex="-1">Group ideas with sections <a class="header-anchor" href="#group-ideas-with-sections" aria-label="Permalink to &quot;Group ideas with sections&quot;">​</a></h1><p>Group sticky notes and other items on a board into titled sections that move together, and hide or lock a section.</p><p>A section is a colored, titled area. Anything that sits mostly inside it belongs to it, so you add an item by dragging it in and remove it by dragging it out.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need <strong>Editor</strong> access. A viewer link can&#39;t change sections.</li><li>The <strong>Retro</strong> and <strong>Brainstorm</strong> templates start with sections already in place. See <a href="/docs/collaborate/templates.html">Templates</a>.</li></ul></div><h2 id="create-a-section" tabindex="-1">Create a section <a class="header-anchor" href="#create-a-section" aria-label="Permalink to &quot;Create a section&quot;">​</a></h2><ol><li>Click empty canvas so nothing is selected.</li><li>Press <code>Shift+S</code>, or click <strong>Section</strong> in the tool dock.</li><li>Drag a rectangle on the canvas, or click for a default size.</li><li>Type a title and press <code>Enter</code>.</li></ol><p>To draw a section around items that are already on the board, select them, right-click one, and select <strong>Create section around selection</strong>. To add one at a spot, right-click empty canvas and select <strong>Insert section</strong>.</p><p><img src="'+a+'" alt="A selected green section titled &quot;Ideas&quot; holding four stickies, with the section controls in the top toolbar"></p><h2 id="add-and-remove-items" tabindex="-1">Add and remove items <a class="header-anchor" href="#add-and-remove-items" aria-label="Permalink to &quot;Add and remove items&quot;">​</a></h2><ul><li>To add an item, drag it into the section. It belongs once most of it is inside.</li><li>To remove an item, drag it out.</li><li>A section can hold smaller sections.</li></ul><p>Items in a section stay selectable on their own. Click one to move or edit it without moving the section.</p><h2 id="move-a-section-with-its-contents" tabindex="-1">Move a section with its contents <a class="header-anchor" href="#move-a-section-with-its-contents" aria-label="Permalink to &quot;Move a section with its contents&quot;">​</a></h2><p>Drag the section from an empty spot inside it. Everything inside moves with it, and connectors attached to those items follow.</p><h2 id="rename-or-recolor-a-section" tabindex="-1">Rename or recolor a section <a class="header-anchor" href="#rename-or-recolor-a-section" aria-label="Permalink to &quot;Rename or recolor a section&quot;">​</a></h2><ol><li>Select the section.</li><li>Click <strong>Rename section</strong> in the top toolbar, or double-click the section. Type a title and press <code>Enter</code>.</li><li>To change the color, pick Gray, Yellow, Green, Blue, Pink, or Purple in the top toolbar.</li></ol><h2 id="hide-the-contents-of-a-section" tabindex="-1">Hide the contents of a section <a class="header-anchor" href="#hide-the-contents-of-a-section" aria-label="Permalink to &quot;Hide the contents of a section&quot;">​</a></h2><p>Select the section and click <strong>Hide contents</strong> in the top toolbar. A cover hides everything inside it for everyone on the board, and its title shows <strong>Hidden</strong>. Click <strong>Reveal contents</strong> to show them again.</p><p>Hidden contents can&#39;t be selected, and they are left out when you <a href="/docs/board/export-and-import.html#download-a-board">download the board</a>.</p><h2 id="lock-a-section" tabindex="-1">Lock a section <a class="header-anchor" href="#lock-a-section" aria-label="Permalink to &quot;Lock a section&quot;">​</a></h2><p>Select the section and click <strong>Lock section</strong> in the top toolbar. A locked section and everything in it can&#39;t be selected or moved, and its title shows <strong>Locked</strong>.</p><p>To unlock it, right-click inside the section and select <strong>Unlock “Ideas”</strong>, named after your section.</p><h2 id="jump-to-a-section" tabindex="-1">Jump to a section <a class="header-anchor" href="#jump-to-a-section" aria-label="Permalink to &quot;Jump to a section&quot;">​</a></h2><p>Click <strong>Sections</strong> (the list icon) in the top toolbar and pick a section. The board zooms to frame it. Locked and hidden sections show an icon in the list.</p><p><img src="'+s+'" alt="Sections menu open in the top toolbar listing Start, Stop, Continue, and Action items"></p><h2 id="delete-a-section" tabindex="-1">Delete a section <a class="header-anchor" href="#delete-a-section" aria-label="Permalink to &quot;Delete a section&quot;">​</a></h2><ul><li>To delete only the section and keep its contents, select it and press <code>Delete</code>.</li><li>To delete the section and everything inside it, right-click it and select <strong>Delete section and contents</strong>.</li></ul><p>Press <code>⌘+Z</code> / <code>Ctrl+Z</code> to undo either one.</p><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>Touch and hold a section to open its menu, which has <strong>Rename section</strong>, <strong>Hide contents</strong>, <strong>Lock section</strong>, and <strong>Delete section and contents</strong>. <strong>Section</strong> is under <strong>More tools</strong> (the ⋯ button) in the tool dock.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/board/stickies-shapes-connectors.html#arrange-items">Stickies, shapes, and connectors</a> to tidy up the items inside a section.</li><li><a href="/docs/board/run-a-retro.html">Run a retro on a board</a> to see sections in a full session.</li><li><a href="/docs/board/export-and-import.html#download-a-board">Download a board</a> to share one section&#39;s result.</li></ul>',31)])])}const b=t(r,[["render",c]]);export{u as __pageData,b as default};
